	static final Set<Integer> ALL_ITEM_IDS;

	static
	{
		Set<Integer> all = new HashSet<>();
		for (Teleport teleport : values())
		{
			all.addAll(teleport.bankItemIds());
		}
		ALL_ITEM_IDS = Set.copyOf(all);
	}

	private final String label;
	/**
	 * Goes to the player's house rather than to a patch.
	 */
	private final boolean viaHouse;
	/**
	 * Any one of these is this teleport, such as each charge of a necklace. Empty for a spell.
	 */
	private final Set<Integer> itemIds;
	/**
	 * Rune id to the amount one cast takes. Empty unless this is a spell.
	 */
	private final Map<Integer, Integer> runes;

	Teleport(String label, Integer... itemIds)
	{
		this(label, false, Set.of(itemIds), Map.of());
	}

	Teleport(String label, Map<Integer, Integer> runes)
	{
		this(label, false, Set.of(), runes);
	}

	Teleport(String label, boolean viaHouse, Set<Integer> itemIds, Map<Integer, Integer> runes)
	{
		this.label = label;
		this.viaHouse = viaHouse;
		this.itemIds = itemIds;
		this.runes = runes;
	}

	boolean isSpell()
	{
		return !runes.isEmpty();
	}

	/**
	 * The items to show in the bank for this teleport.
	 */
	Set<Integer> bankItemIds()
	{
		if (!isSpell())
		{
			return itemIds;
		}

		Set<Integer> ids = new HashSet<>(runes.keySet());
		ids.addAll(RUNE_POUCHES);
		return ids;
	}

	@Override
	public String toString()
	{
		return label;
	}

	/**
	 * @param idsAndAmounts rune id, amount, rune id, amount, ...
	 */
	private static Map<Integer, Integer> runes(int... idsAndAmounts)
	{
		Map<Integer, Integer> runes = new LinkedHashMap<>();
		for (int i = 0; i < idsAndAmounts.length; i += 2)
		{
			runes.put(idsAndAmounts[i], idsAndAmounts[i + 1]);
		}
		return runes;
	}
}

package com.plugandplant;

import java.util.Arrays;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BankAndRouteTest
{
	private static BankFilterSpec spec(Object... sectionsAndItems)
	{
		Map<BankSection, List<Integer>> sections = new LinkedHashMap<>();
		for (int i = 0; i < sectionsAndItems.length; i += 2)
		{
			@SuppressWarnings("unchecked")
			List<Integer> items = (List<Integer>) sectionsAndItems[i + 1];
			sections.put((BankSection) sectionsAndItems[i], items);
		}
		return new BankFilterSpec(sections);
	}

	@Test
	public void bankFilterShowsEachItemInItsSection()
	{
		BankFilterSpec spec = spec(
			BankSection.HERB_SEEDS, RunItems.HERB_SEEDS,
			BankSection.EQUIPMENT, RunItems.EQUIPMENT,
			BankSection.TELEPORTS, List.of(ItemID.ECTOPHIAL));

		assertEquals(BankSection.HERB_SEEDS, spec.sectionOf(ItemID.RANARR_SEED));
		assertEquals(BankSection.EQUIPMENT, spec.sectionOf(ItemID.SPADE));
		assertEquals(BankSection.TELEPORTS, spec.sectionOf(ItemID.ECTOPHIAL));
		assertNull(spec.sectionOf(ItemID.WATERMELON_SEED));
		assertNull(spec.sectionOf(ItemID.COINS));
	}

	@Test
	public void itemListedInTwoSectionsGoesInTheFirst()
	{
		// Coconuts pay for magic trees; a coconut is also a teleport nowhere, but say it were
		BankFilterSpec spec = spec(BankSection.PAYMENTS, List.of(ItemID.COCONUT), BankSection.TELEPORTS, List.of(ItemID.COCONUT));

		assertEquals(BankSection.PAYMENTS, spec.sectionOf(ItemID.COCONUT));
	}

	@Test
	public void bankItemsAreArrangedInSectionsUnderAHeadingRow()
	{
		BankFilterSpec spec = spec(
			BankSection.HERB_SEEDS, RunItems.HERB_SEEDS,
			BankSection.ALLOTMENT_SEEDS, RunItems.ALLOTMENT_SEEDS,
			BankSection.EQUIPMENT, RunItems.EQUIPMENT,
			BankSection.TELEPORTS, List.of(ItemID.ECTOPHIAL));
		// In bank order, which isn't the order they should be shown in; coins aren't part of the filter
		List<Integer> bank = List.of(ItemID.ECTOPHIAL, ItemID.TORSTOL_SEED, ItemID.COINS, ItemID.DIBBER, ItemID.GUAM_SEED, ItemID.SPADE, ItemID.POTATO_SEED);

		BankFilterSpec.Arrangement arrangement = spec.arrange(bank);

		int[] expected = new int[8 * 8];
		Arrays.fill(expected, -1);
		expected[8] = ItemID.GUAM_SEED;
		expected[9] = ItemID.TORSTOL_SEED;
		expected[24] = ItemID.POTATO_SEED;
		expected[40] = ItemID.SPADE;
		expected[41] = ItemID.DIBBER;
		expected[56] = ItemID.ECTOPHIAL;
		assertArrayEquals(expected, arrangement.getSlots());

		Map<BankSection, Integer> headings = new LinkedHashMap<>();
		headings.put(BankSection.HERB_SEEDS, 0);
		headings.put(BankSection.ALLOTMENT_SEEDS, 2);
		headings.put(BankSection.EQUIPMENT, 4);
		headings.put(BankSection.TELEPORTS, 6);
		assertEquals(headings, arrangement.getHeadingRows());
	}

	@Test
	public void sectionLongerThanARowPushesTheNextOneDown()
	{
		BankFilterSpec spec = spec(BankSection.HERB_SEEDS, RunItems.HERB_SEEDS, BankSection.EQUIPMENT, RunItems.EQUIPMENT);
		BankFilterSpec.Arrangement arrangement = spec.arrange(
			List.of(ItemID.GUAM_SEED, ItemID.MARRENTILL_SEED, ItemID.TARROMIN_SEED, ItemID.HARRALANDER_SEED, ItemID.RANARR_SEED,
				ItemID.TOADFLAX_SEED, ItemID.IRIT_SEED, ItemID.AVANTOE_SEED, ItemID.KWUARM_SEED, ItemID.RAKE));

		assertEquals(Integer.valueOf(0), arrangement.getHeadingRows().get(BankSection.HERB_SEEDS));
		// Nine herb seeds take two rows, after the heading row
		assertEquals(Integer.valueOf(3), arrangement.getHeadingRows().get(BankSection.EQUIPMENT));
		assertEquals(ItemID.KWUARM_SEED, arrangement.getSlots()[16]);
		assertEquals(ItemID.RAKE, arrangement.getSlots()[32]);
	}

	@Test
	public void emptyBankGivesAnEmptyLayout()
	{
		BankFilterSpec.Arrangement arrangement = spec(BankSection.HERB_SEEDS, RunItems.HERB_SEEDS).arrange(List.of(ItemID.COINS));

		assertEquals(0, arrangement.getSlots().length);
		assertTrue(arrangement.getHeadingRows().isEmpty());
	}

	private static Route route(RunType runType, Map<FarmLocation, List<Map<Integer, Integer>>> stops, boolean carriedOnly,
		boolean house, boolean spells)
	{
		return new Route(runType, stops, carriedOnly, house, spells, Set.of());
	}

	@Test
	public void pathMessageTargetsPlainPointsWithoutSeedRequirements()
	{
		Map<FarmLocation, List<Map<Integer, Integer>>> stops = new LinkedHashMap<>();
		stops.put(FarmLocation.FALADOR, List.of());
		stops.put(FarmLocation.WEISS, List.of());

		Map<String, Object> data = ShortestPathRouter.pathMessage(route(RunType.HERB, stops, false, false, false));

		assertEquals(List.of(new WorldPoint(3058, 3311, 0), new WorldPoint(2848, 3934, 0)), data.get("target"));
		assertNull(data.get("config"));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void pathMessagePassesEachStopsSeedRequirements()
	{
		Map<FarmLocation, List<Map<Integer, Integer>>> stops = new LinkedHashMap<>();
		stops.put(FarmLocation.FARMING_GUILD, List.of(Map.of(ItemID.IRIT_SEED, 1)));
		stops.put(FarmLocation.WEISS, List.of());

		List<Object> targets = (List<Object>) ShortestPathRouter.pathMessage(route(RunType.HERB, stops, false, false, false)).get("target");

		assertEquals(2, targets.size());
		Map<String, Object> guild = (Map<String, Object>) targets.get(0);
		assertEquals(FarmLocation.FARMING_GUILD.patches(PatchType.HERB).get(0).getPoint(), guild.get("point"));
		assertEquals(List.of(Map.of(ItemID.IRIT_SEED, 1)), guild.get("requirements"));
		assertEquals(FarmLocation.WEISS.patches(PatchType.HERB).get(0).getPoint(), targets.get(1));
	}

	@Test
	@SuppressWarnings("unchecked")
	public void treeRunGoesToTheGuildsTreeRatherThanItsHerbPatch()
	{
		Map<FarmLocation, List<Map<Integer, Integer>>> stops = Map.of(FarmLocation.FARMING_GUILD, List.of());

		List<Object> targets = (List<Object>) ShortestPathRouter.pathMessage(route(RunType.TREE, stops, false, false, false)).get("target");

		assertEquals(List.of(new WorldPoint(1232, 3736, 0)), targets);
	}

	@Test
	public void shortestPathsAnswerIsMatchedToTheStopItLeadsTo()
	{
		Map<FarmLocation, List<Map<Integer, Integer>>> stops = new LinkedHashMap<>();
		stops.put(FarmLocation.LUMBRIDGE, List.of());
		stops.put(FarmLocation.FARMING_GUILD, List.of());
		Route route = route(RunType.TREE, stops, false, false, false);

		assertEquals(FarmLocation.FARMING_GUILD, ShortestPathRouter.stopAt(route, new WorldPoint(1232, 3736, 0)));
		// A tile beside the patch, when the patch itself can't be stood on
		assertEquals(FarmLocation.LUMBRIDGE, ShortestPathRouter.stopAt(route, new WorldPoint(3194, 3232, 0)));
		assertNull(ShortestPathRouter.stopAt(route, new WorldPoint(3000, 3000, 0)));
	}

	@Test
	public void pathMessageOnlyOverridesTheShortestPathSettingsItNeeds()
	{
		Map<FarmLocation, List<Map<Integer, Integer>>> stops = Map.of(FarmLocation.FALADOR, List.of());

		assertEquals(Map.of("useTeleportationItems", "Inventory"),
			ShortestPathRouter.pathMessage(route(RunType.HERB, stops, true, false, false)).get("config"));
		assertEquals(Map.of("usePoh", true, "useTeleportationSpells", true),
			ShortestPathRouter.pathMessage(route(RunType.HERB, stops, false, true, true)).get("config"));
	}

	@Test
	public void contractVarbitValuesMatchTheirCrops()
	{
		assertEquals(FarmingContract.IRIT, FarmingContract.fromVarbit(26));
		assertEquals(FarmingContract.WATERMELON, FarmingContract.fromVarbit(46));
		assertEquals(FarmingContract.MAGIC, FarmingContract.fromVarbit(11));
		assertEquals(FarmingContract.DRAGONFRUIT, FarmingContract.fromVarbit(19));
		// A bush contract isn't one a run grows
		assertNull(FarmingContract.fromVarbit(1));
		for (FarmingContract contract : FarmingContract.values())
		{
			assertTrue(contract.getType().getSeeds().contains(contract.getSeed()));
		}
	}

	@Test
	public void everyPatchHasItsOwnTimeTrackingKey()
	{
		Set<String> keys = new HashSet<>();
		for (FarmLocation location : FarmLocation.values())
		{
			for (FarmPatch patch : location.getPatches())
			{
				assertTrue(patch.toString(), keys.add(patch.timeTrackingKey()));
			}
		}
		// Herb runs: seven locations with two allotments and a flower patch, Harmony with one allotment,
		// and two with a herb patch alone. Tree runs: seven trees and seven fruit trees.
		assertEquals(7 * 4 + 2 + 2 + 7 + 7, keys.size());
	}

	@Test
	public void eachRunHasItsLocations()
	{
		assertEquals(10, FarmLocation.of(RunType.HERB).size());
		// The guild and the Gnome Stronghold each have a tree and a fruit tree
		assertEquals(12, FarmLocation.of(RunType.TREE).size());
		assertTrue(FarmLocation.of(RunType.TREE).contains(FarmLocation.FARMING_GUILD));
		assertFalse(FarmLocation.of(RunType.HERB).contains(FarmLocation.LUMBRIDGE));
		for (FarmLocation location : FarmLocation.of(RunType.TREE))
		{
			for (FarmPatch tree : location.anchors(RunType.TREE))
			{
				assertTrue(tree.toString(), tree.getGardener() > 0);
			}
		}
	}

	@Test
	public void teleportChoicesAreAnyThenTheLocationsOwnThenTheHouseThenNone()
	{
		for (FarmLocation location : FarmLocation.values())
		{
			List<Teleport> choices = location.teleportChoices();
			assertEquals(Teleport.ANY, choices.get(0));
			assertEquals(Teleport.NONE, choices.get(choices.size() - 1));
			assertEquals(location.getTeleports(), choices.subList(1, 1 + location.getTeleports().size()));
			assertTrue(choices.containsAll(List.of(Teleport.HOUSE_TAB, Teleport.HOUSE_SPELL, Teleport.HOUSE_CAPE)));
			assertEquals(choices.size(), new HashSet<>(choices).size());
		}
	}

	@Test
	public void anyTeleportMeansTheLocationsItemsButNotItsSpells()
	{
		assertEquals(List.of(Teleport.ECTOPHIAL, Teleport.FENKENSTRAIN_TAB), FarmLocation.MORYTANIA.teleportsFor(Teleport.ANY));
		assertEquals(List.of(Teleport.FENKENSTRAIN_SPELL), FarmLocation.MORYTANIA.teleportsFor(Teleport.FENKENSTRAIN_SPELL));
		assertEquals(List.of(Teleport.HOUSE_SPELL), FarmLocation.MORYTANIA.teleportsFor(Teleport.HOUSE_SPELL));
		assertEquals(List.of(), FarmLocation.MORYTANIA.teleportsFor(Teleport.NONE));
		// A teleport that doesn't go here counts as no preference
		assertEquals(List.of(Teleport.ECTOPHIAL, Teleport.FENKENSTRAIN_TAB), FarmLocation.MORYTANIA.teleportsFor(Teleport.ICY_BASALT));
	}

	@Test
	public void recommendedOrderCoversEachRunsLocationsOnce()
	{
		for (RunType runType : RunType.values())
		{
			List<FarmLocation> order = FarmLocation.recommendedOrder(runType);
			assertEquals(order.size(), new HashSet<>(order).size());
			assertEquals(new HashSet<>(FarmLocation.of(runType)), new HashSet<>(order));
		}
	}

	@Test
	public void stopsFollowTheRecommendedOrderWithTheOneThePlayerIsAtFirst()
	{
		Set<FarmLocation> stops = Set.of(FarmLocation.HARMONY, FarmLocation.CATHERBY, FarmLocation.FALADOR, FarmLocation.HOSIDIUS);

		assertEquals(List.of(FarmLocation.FALADOR, FarmLocation.CATHERBY, FarmLocation.HOSIDIUS, FarmLocation.HARMONY),
			PlugAndPlantPlugin.orderedStops(RunType.HERB, stops, null));
		// Standing at the Hosidius herb patch
		assertEquals(List.of(FarmLocation.HOSIDIUS, FarmLocation.FALADOR, FarmLocation.CATHERBY, FarmLocation.HARMONY),
			PlugAndPlantPlugin.orderedStops(RunType.HERB, stops, new WorldPoint(1738, 3550, 0)));
	}

	@Test
	public void brimhavenCanBeReachedThroughArdougne()
	{
		assertTrue(FarmLocation.BRIMHAVEN.getTeleports().containsAll(List.of(Teleport.ARDOUGNE_TAB, Teleport.ARDOUGNE_SPELL)));
	}

	@Test
	public void spellShowsItsRunesAndRunePouchesInTheBank()
	{
		Collection<Integer> items = Teleport.FALADOR_SPELL.bankItemIds();
		assertTrue(items.containsAll(Set.of(ItemID.LAWRUNE, ItemID.AIRRUNE, ItemID.WATERRUNE, ItemID.BH_RUNE_POUCH)));
		assertFalse(items.contains(ItemID.FIRERUNE));
		assertEquals(Set.of(ItemID.TELETAB_FENK), Teleport.FENKENSTRAIN_TAB.bankItemIds());
	}
}

package com.plugandplant;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ChecklistTest
{
	private static final Checklist.Options PLAIN = new Checklist.Options(RunType.HERB, false, false, false, false, false, List.of());

	private final Map<FarmPatch, PatchState> states = new HashMap<>();
	private final Map<FarmLocation, LocationSettings> settings = new EnumMap<>(FarmLocation.class);
	private final Map<Integer, Integer> items = new HashMap<>();
	private final Map<Integer, Integer> pouchRunes = new HashMap<>();
	private final Map<Integer, Integer> stored = new HashMap<>();
	private final Set<Integer> unlimitedRunes = new HashSet<>();
	private boolean seedBoxUnknown;
	private final Set<FarmPatch> justPlanted = new HashSet<>();

	private void ready(FarmPatch patch)
	{
		ready(patch, PatchStatus.READY);
	}

	private void ready(FarmPatch patch, PatchStatus status)
	{
		states.put(patch, new PatchState(status, 0));
	}

	private List<ChecklistItem> build(Checklist.Options options)
	{
		return build(options, null);
	}

	private List<ChecklistItem> build(Checklist.Options options, FarmingContract contract)
	{
		RunType runType = options.getRunType();
		List<FarmLocation> stops = new ArrayList<>();
		for (FarmLocation location : FarmLocation.of(runType))
		{
			if (location.anchors(runType).stream()
				.anyMatch(patch -> states.getOrDefault(patch, PatchState.UNKNOWN).getStatus().needsVisit()))
			{
				stops.add(location);
			}
		}
		Carried carried = new Carried(items, pouchRunes, unlimitedRunes, stored, seedBoxUnknown);
		RunPlan plan = RunPlan.of(stops, states, Set.of(), Set.of(), justPlanted,
			new RunPlan.Options(runType, options.isAllotments(), options.isFlowers(), options.isCompost(), options.isProtect(), 99),
			carried, contract);
		return Checklist.build(plan, states, settings, carried, options, contract);
	}

	private static ChecklistItem find(List<ChecklistItem> checklist, String label)
	{
		return checklist.stream().filter(item -> item.getLabel().equals(label)).findFirst().orElse(null);
	}

	@Test
	public void seedsOfAKindAreCountedTogether()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		ready(FarmLocation.CATHERBY.patches(PatchType.HERB).get(0));
		ready(FarmLocation.ARDOUGNE.patches(PatchType.HERB).get(0));
		items.put(ItemID.RANARR_SEED, 1);
		items.put(ItemID.TORSTOL_SEED, 1);

		assertEquals(new ChecklistItem("Herb seeds", "2 / 3", ChecklistItem.State.MISSING), find(build(PLAIN), "Herb seeds"));

		items.put(ItemID.GUAM_SEED, 5);
		assertEquals(new ChecklistItem("Herb seeds", "7 / 3", ChecklistItem.State.GOOD), find(build(PLAIN), "Herb seeds"));
		assertNull(find(build(PLAIN), "Allotment seeds"));
	}

	@Test
	public void seedBoxNotYetLookedInMakesAShortfallUnsure()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		items.put(ItemID.SEED_BOX_OPEN, 1);
		seedBoxUnknown = true;

		assertEquals(new ChecklistItem("Herb seeds", "0 / 1 + box", ChecklistItem.State.UNSURE), find(build(PLAIN), "Herb seeds"));

		// Once its contents are known they are counted like any other seeds
		seedBoxUnknown = false;
		assertEquals(new ChecklistItem("Herb seeds", "0 / 1", ChecklistItem.State.MISSING), find(build(PLAIN), "Herb seeds"));
	}

	@Test
	public void allotmentAndFlowerSeedsShowHowManyPatchesTheyPlant()
	{
		Checklist.Options both = new Checklist.Options(RunType.HERB, true, true, false, false, false, List.of());
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		items.put(ItemID.WATERMELON_SEED, 7);
		items.put(ItemID.POTATO_SEED, 3);

		List<ChecklistItem> checklist = build(both);
		assertEquals(new ChecklistItem("Allotment seeds", "3 patches", ChecklistItem.State.GOOD), find(checklist, "Allotment seeds"));
		assertEquals(new ChecklistItem("Flower seeds", "None", ChecklistItem.State.UNSURE), find(checklist, "Flower seeds"));
		assertNull(find(build(PLAIN), "Allotment seeds"));
	}

	@Test
	public void contractSeedIsAskedForWhenTheGuildIsAStop()
	{
		ready(FarmLocation.FARMING_GUILD.patches(PatchType.HERB).get(0));
		items.put(ItemID.RANARR_SEED, 1);

		assertEquals(new ChecklistItem("Contract: Irit seed", "Missing", ChecklistItem.State.MISSING),
			find(build(PLAIN, FarmingContract.IRIT), "Contract: Irit seed"));

		items.put(ItemID.IRIT_SEED, 1);
		assertEquals(ChecklistItem.State.GOOD, find(build(PLAIN, FarmingContract.IRIT), "Contract: Irit seed").getState());
	}

	@Test
	public void contractIsLeftOffWhenTheGuildIsNotAStop()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));

		assertNull(find(build(PLAIN, FarmingContract.IRIT), "Contract: Irit seed"));
	}

	@Test
	public void compostIsCountedPerPatchUnlessBottomless()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		ready(FarmLocation.CATHERBY.patches(PatchType.HERB).get(0));
		Checklist.Options withCompost = new Checklist.Options(RunType.HERB, false, false, true, false, false, List.of());
		items.put(ItemID.BUCKET_ULTRACOMPOST, 1);

		assertEquals(new ChecklistItem("Compost", "1 / 2", ChecklistItem.State.UNSURE), find(build(withCompost), "Compost"));
		assertNull(find(build(PLAIN), "Compost"));

		items.put(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 1);
		assertEquals(new ChecklistItem("Compost", "Bottomless", ChecklistItem.State.GOOD), find(build(withCompost), "Compost"));
	}

	@Test
	public void toolsAreCarriedAtTheLeprechaunOrMissing()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		items.put(ItemID.SPADE, 1);
		stored.put(ItemID.DIBBER, 1);

		List<ChecklistItem> checklist = build(PLAIN);
		assertEquals(ChecklistItem.State.GOOD, find(checklist, "Spade").getState());
		assertEquals(new ChecklistItem("Seed dibber", "At leprechaun", ChecklistItem.State.STORED), find(checklist, "Seed dibber"));
		// Magic secateurs only add to the yield, so they aren't missing
		assertEquals(ChecklistItem.State.UNSURE, find(checklist, "Magic secateurs").getState());

		stored.clear();
		assertEquals(ChecklistItem.State.MISSING, find(build(PLAIN), "Seed dibber").getState());
		// Only asked for when a patch needs it
		assertNull(find(checklist, "Rake"));
		assertNull(find(checklist, "Plant cure"));
	}

	@Test
	public void particularTeleportIsMissingUntilCarried()
	{
		ready(FarmLocation.MORYTANIA.patches(PatchType.HERB).get(0));
		settings.put(FarmLocation.MORYTANIA, new LocationSettings(true, Teleport.ECTOPHIAL));

		assertEquals(new ChecklistItem("Morytania: Ectophial", "Missing", ChecklistItem.State.MISSING),
			find(build(PLAIN), "Morytania: Ectophial"));

		items.put(ItemID.ECTOPHIAL_EMPTY, 1);
		assertEquals(ChecklistItem.State.GOOD, find(build(PLAIN), "Morytania: Ectophial").getState());
	}

	@Test
	public void anyTeleportIsSatisfiedByAnyOfTheLocationsItems()
	{
		ready(FarmLocation.MORYTANIA.patches(PatchType.HERB).get(0));

		assertEquals(new ChecklistItem("Morytania teleport", "None", ChecklistItem.State.UNSURE), find(build(PLAIN), "Morytania teleport"));

		items.put(ItemID.TELETAB_FENK, 2);
		assertEquals(ChecklistItem.State.GOOD, find(build(PLAIN), "Morytania teleport").getState());
	}

	@Test
	public void noTeleportLeavesTheLocationOffTheChecklist()
	{
		ready(FarmLocation.MORYTANIA.patches(PatchType.HERB).get(0));
		settings.put(FarmLocation.MORYTANIA, new LocationSettings(true, Teleport.NONE));

		assertNull(find(build(PLAIN), "Morytania teleport"));
	}

	@Test
	public void spellRunesAreFoundInTheInventoryAndRunePouch()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		settings.put(FarmLocation.FALADOR, new LocationSettings(true, Teleport.FALADOR_SPELL));

		// Falador Teleport takes a law, three airs and a water
		items.put(ItemID.LAWRUNE, 10);
		items.put(ItemID.AIRRUNE, 2);
		assertEquals(new ChecklistItem("Falador: Falador spell", "Runes not found", ChecklistItem.State.UNSURE),
			find(build(PLAIN), "Falador: Falador spell"));

		pouchRunes.put(ItemID.AIRRUNE, 1);
		pouchRunes.put(ItemID.WATERRUNE, 500);
		assertEquals(ChecklistItem.State.GOOD, find(build(PLAIN), "Falador: Falador spell").getState());
	}

	@Test
	public void houseTeleportIsOfferedEverywhere()
	{
		ready(FarmLocation.WEISS.patches(PatchType.HERB).get(0));
		settings.put(FarmLocation.WEISS, new LocationSettings(true, Teleport.HOUSE_TAB));
		items.put(ItemID.POH_TABLET_TELEPORTTOHOUSE, 3);

		assertEquals(new ChecklistItem("Weiss: House tab", "Yes", ChecklistItem.State.GOOD), find(build(PLAIN), "Weiss: House tab"));
	}

	@Test
	public void gracefulAndVolcanicAshAreOptional()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		assertNull(find(build(PLAIN), "Graceful"));
		assertNull(find(build(PLAIN), "Volcanic ash"));

		// Two recolours of the hood count as one piece
		List<List<Integer>> pieces = List.of(List.of(ItemID.GRACEFUL_HOOD, 13579), List.of(ItemID.GRACEFUL_TOP));
		Checklist.Options options = new Checklist.Options(RunType.HERB, false, false, false, false, true, pieces);
		items.put(13579, 1);
		items.put(ItemID.FOSSIL_VOLCANIC_ASH, 40);

		List<ChecklistItem> checklist = build(options);
		assertEquals(new ChecklistItem("Graceful", "1 / 2", ChecklistItem.State.MISSING), find(checklist, "Graceful"));
		assertEquals(new ChecklistItem("Volcanic ash", "40", ChecklistItem.State.GOOD), find(checklist, "Volcanic ash"));
	}

	private static final Checklist.Options TREES = new Checklist.Options(RunType.TREE, false, false, false, true, false, List.of());

	@Test
	public void treeRunAsksForSaplingsOfBothKinds()
	{
		ready(FarmLocation.LUMBRIDGE.patches(PatchType.TREE).get(0), PatchStatus.CHECK_HEALTH);
		ready(FarmLocation.GNOME_STRONGHOLD.patches(PatchType.TREE).get(0), PatchStatus.STUMP);
		ready(FarmLocation.GNOME_STRONGHOLD.patches(PatchType.FRUIT_TREE).get(0), PatchStatus.GROWN);
		items.put(ItemID.PLANTPOT_YEW_SAPLING, 2);

		List<ChecklistItem> checklist = build(TREES);
		assertEquals(new ChecklistItem("Tree saplings", "2 / 2", ChecklistItem.State.GOOD), find(checklist, "Tree saplings"));
		assertEquals(new ChecklistItem("Fruit tree saplings", "0 / 1", ChecklistItem.State.MISSING), find(checklist, "Fruit tree saplings"));
		// A health check and a grown tree each take a removal; a stump is dug up
		assertEquals(new ChecklistItem("Coins to remove trees", "0 / 400", ChecklistItem.State.UNSURE), find(checklist, "Coins to remove trees"));
		assertNull(find(checklist, "Seed dibber"));
		assertNull(find(checklist, "Herb seeds"));
	}

	@Test
	public void paymentsFollowTheSaplingsCarried()
	{
		ready(FarmLocation.LUMBRIDGE.patches(PatchType.TREE).get(0), PatchStatus.CHECK_HEALTH);
		ready(FarmLocation.VARROCK.patches(PatchType.TREE).get(0), PatchStatus.CHECK_HEALTH);
		ready(FarmLocation.CATHERBY_ORCHARD.patches(PatchType.FRUIT_TREE).get(0), PatchStatus.CHECK_HEALTH);
		ready(FarmLocation.BRIMHAVEN.patches(PatchType.FRUIT_TREE).get(0), PatchStatus.CHECK_HEALTH);
		// A magic and a yew tree; one dragonfruit tree, which shares coconuts with magic, and one without a sapling
		items.put(ItemID.PLANTPOT_MAGIC_TREE_SAPLING, 1);
		items.put(ItemID.PLANTPOT_YEW_SAPLING, 1);
		items.put(ItemID.PLANTPOT_DRAGONFRUIT_SAPLING, 1);
		items.put(ItemID.COCONUT, 30);

		List<ChecklistItem> checklist = build(TREES);
		assertEquals(new ChecklistItem("Pay: coconuts", "30 / 40", ChecklistItem.State.MISSING), find(checklist, "Pay: coconuts"));
		assertEquals(new ChecklistItem("Pay: cactus spines", "0 / 10", ChecklistItem.State.MISSING), find(checklist, "Pay: cactus spines"));
		assertEquals(new ChecklistItem("Pay: for 1 more tree", "Bring saplings", ChecklistItem.State.UNSURE),
			find(checklist, "Pay: for 1 more tree"));
	}

	@Test
	public void treePlantedOnTheRunIsPaidForWhatIsGrowing()
	{
		// Planted at the stop the player is at, so it was a stop when the run started
		FarmPatch tree = FarmLocation.LUMBRIDGE.patches(PatchType.TREE).get(0);
		states.put(tree, new PatchState(PatchStatus.GROWING, 123, Sapling.MAPLE));
		justPlanted.add(tree);
		Carried carried = new Carried(items, pouchRunes);
		RunPlan plan = RunPlan.of(List.of(FarmLocation.LUMBRIDGE), states, Set.of(tree), Set.of(), justPlanted,
			new RunPlan.Options(RunType.TREE, false, false, false, true, 99), carried, null);

		List<ChecklistItem> checklist = Checklist.build(plan, states, settings, carried, TREES, null);
		assertEquals(new ChecklistItem("Pay: basket of oranges", "0 / 1", ChecklistItem.State.MISSING),
			find(checklist, "Pay: basket of oranges"));
	}

	@Test
	public void compostAtTheLeprechaunMakesUpTheShortfall()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		ready(FarmLocation.CATHERBY.patches(PatchType.HERB).get(0));
		ready(FarmLocation.ARDOUGNE.patches(PatchType.HERB).get(0));
		Checklist.Options withCompost = new Checklist.Options(RunType.HERB, false, false, true, false, false, List.of());
		items.put(ItemID.BUCKET_ULTRACOMPOST, 1);
		stored.put(ItemID.BUCKET_SUPERCOMPOST, 5);

		assertEquals(new ChecklistItem("Compost", "1 / 3, 5 at leprechaun", ChecklistItem.State.STORED), find(build(withCompost), "Compost"));

		stored.clear();
		stored.put(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 1);
		assertEquals(new ChecklistItem("Compost", "Bottomless at leprechaun", ChecklistItem.State.STORED), find(build(withCompost), "Compost"));
	}

	@Test
	public void staffAndCombinationRunesCountTowardsASpell()
	{
		ready(FarmLocation.FALADOR.patches(PatchType.HERB).get(0));
		settings.put(FarmLocation.FALADOR, new LocationSettings(true, Teleport.FALADOR_SPELL));
		// Falador Teleport takes a law, three airs and a water
		items.put(ItemID.LAWRUNE, 1);
		items.put(ItemID.WATERRUNE, 1);
		assertEquals(ChecklistItem.State.UNSURE, find(build(PLAIN), "Falador: Falador spell").getState());

		unlimitedRunes.add(ItemID.AIRRUNE);
		assertEquals(ChecklistItem.State.GOOD, find(build(PLAIN), "Falador: Falador spell").getState());

		// Mist runes count as both air and water
		unlimitedRunes.clear();
		items.remove(ItemID.WATERRUNE);
		pouchRunes.put(ItemID.MISTRUNE, 3);
		assertEquals(ChecklistItem.State.GOOD, find(build(PLAIN), "Falador: Falador spell").getState());
	}

	@Test
	public void staffVariantsAndTomesSupplyTheirRunes()
	{
		assertEquals(Set.of(ItemID.AIRRUNE), Runes.suppliedBy(ItemID.STAFF_OF_AIR));
		assertEquals(Set.of(ItemID.AIRRUNE, ItemID.WATERRUNE), Runes.suppliedBy(ItemID.MYSTIC_MIST_BATTLESTAFF));
		assertEquals(Set.of(ItemID.FIRERUNE), Runes.suppliedBy(ItemID.TOME_OF_FIRE));
		assertEquals(Set.of(), Runes.suppliedBy(ItemID.TOME_OF_FIRE_UNCHARGED));
		assertEquals(Set.of(), Runes.suppliedBy(ItemID.SPADE));
	}
}

package com.plugandplant;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class PatchDecoderTest
{
	// 1,000,000 is 400 seconds into both a 20 and a 10 minute growth tick, which started at 999,600
	private static final long SEEN_AT = 1_000_000;
	private static final long SEEN_TICK = 999_600;
	private static final long MINUTE = 60;

	private static final int GROWING = 0;
	private static final int HARVESTABLE = 1;
	private static final int DISEASED = 2;
	private static final int DEAD = 3;
	private static final int WEEDS = 4;
	private static final int RAKED = 5;
	private static final int UNUSED = 6;
	/**
	 * Every herb varbit range from Time Tracking's PatchImplementation.HERB: {first, last, kind}.
	 * Herbs have four growing values, so a growing range's first value has four growth ticks to go.
	 */
	private static final int[][] HERB_RANGES = {
		{0, 2, WEEDS}, {3, 3, RAKED},
		{4, 7, GROWING}, {8, 10, HARVESTABLE},
		{11, 14, GROWING}, {15, 17, HARVESTABLE},
		{18, 21, GROWING}, {22, 24, HARVESTABLE},
		{25, 28, GROWING}, {29, 31, HARVESTABLE},
		{32, 35, GROWING}, {36, 38, HARVESTABLE},
		{39, 42, GROWING}, {43, 45, HARVESTABLE},
		{46, 49, GROWING}, {50, 52, HARVESTABLE},
		{53, 56, GROWING}, {57, 59, HARVESTABLE},
		{60, 63, GROWING}, {64, 66, HARVESTABLE},
		{67, 67, WEEDS},
		{68, 71, GROWING}, {72, 74, HARVESTABLE},
		{75, 78, GROWING}, {79, 81, HARVESTABLE},
		{82, 85, GROWING}, {86, 88, HARVESTABLE},
		{89, 92, GROWING}, {93, 95, HARVESTABLE},
		{96, 99, GROWING}, {100, 102, HARVESTABLE},
		{103, 106, GROWING}, {107, 109, HARVESTABLE},
		{110, 127, UNUSED},
		{128, 169, DISEASED},
		{170, 172, DEAD},
		{173, 175, DISEASED},
		{176, 191, WEEDS},
		{192, 195, GROWING}, {196, 197, HARVESTABLE},
		{198, 200, DISEASED},
		{201, 203, DEAD},
		{204, 219, WEEDS},
		{220, 220, UNUSED},
		{221, 255, WEEDS},
	};

	@Test
	public void everyHerbVarbitValueDecodesAsTimeTrackingDoes()
	{
		int next = 0;
		for (int[] range : HERB_RANGES)
		{
			assertEquals("ranges must be contiguous", next, range[0]);
			for (int value = range[0]; value <= range[1]; value++)
			{
				PatchState state = predict(PatchType.HERB, value + ":" + SEEN_AT, SEEN_AT);
				String message = "value " + value;
				if (range[2] == GROWING)
				{
					int ticksLeft = 4 - (value - range[0]);
					assertEquals(message, new PatchState(PatchStatus.GROWING, SEEN_TICK + ticksLeft * 20 * MINUTE), state);
				}
				else
				{
					assertEquals(message, new PatchState(expectedStatus(range[2]), 0), state);
				}
			}
			next = range[1] + 1;
		}
		assertEquals(256, next);
	}

	private static PatchStatus expectedStatus(int kind)
	{
		switch (kind)
		{
			case HARVESTABLE:
				return PatchStatus.READY;
			case DISEASED:
				return PatchStatus.DISEASED;
			case DEAD:
				return PatchStatus.DEAD;
			case WEEDS:
				return PatchStatus.WEEDS;
			case RAKED:
				return PatchStatus.EMPTY;
			default:
				return PatchStatus.UNKNOWN;
		}
	}

	@Test
	public void growingCropTurnsReadyAtItsLastGrowthTick()
	{
		long readyAt = SEEN_TICK + 4 * 20 * MINUTE;
		// 32 is a ranarr at growth stage 0
		assertEquals(new PatchState(PatchStatus.GROWING, readyAt), predict(PatchType.HERB, "32:" + SEEN_AT, readyAt - 1));
		assertEquals(new PatchState(PatchStatus.READY, 0), predict(PatchType.HERB, "32:" + SEEN_AT, readyAt));
	}

	@Test
	public void allotmentsGrowInTenMinuteTicksAndCropsDifferInStages()
	{
		// 6 is a freshly planted potato, which has four growth ticks to go
		assertEquals(new PatchState(PatchStatus.GROWING, SEEN_TICK + 4 * 10 * MINUTE), predict(PatchType.ALLOTMENT, "6:" + SEEN_AT, SEEN_AT));
		// 52 is a freshly planted watermelon, which has eight
		assertEquals(new PatchState(PatchStatus.GROWING, SEEN_TICK + 8 * 10 * MINUTE), predict(PatchType.ALLOTMENT, "52:" + SEEN_AT, SEEN_AT));
		assertEquals(new PatchState(PatchStatus.GROWING, SEEN_TICK + 10 * MINUTE), predict(PatchType.ALLOTMENT, "59:" + SEEN_AT, SEEN_AT));

		assertEquals(PatchStatus.READY, predict(PatchType.ALLOTMENT, "10:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.READY, predict(PatchType.ALLOTMENT, "60:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.DISEASED, predict(PatchType.ALLOTMENT, "181:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.DEAD, predict(PatchType.ALLOTMENT, "245:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.WEEDS, predict(PatchType.ALLOTMENT, "0:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.EMPTY, predict(PatchType.ALLOTMENT, "3:" + SEEN_AT, SEEN_AT).getStatus());
	}

	@Test
	public void flowersGrowInFiveMinuteTicks()
	{
		// 1,000,000 is 100 seconds into a 5 minute growth tick that started at 999,900; 8 is a freshly planted marigold
		assertEquals(new PatchState(PatchStatus.GROWING, 999_900 + 4 * 5 * MINUTE), predict(PatchType.FLOWER, "8:" + SEEN_AT, SEEN_AT));
		assertEquals(PatchStatus.READY, predict(PatchType.FLOWER, "12:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.DISEASED, predict(PatchType.FLOWER, "137:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.DEAD, predict(PatchType.FLOWER, "201:" + SEEN_AT, SEEN_AT).getStatus());
	}

	@Test
	public void growthTicksShiftByTheAccountsTickOffset()
	{
		// A 5 minute offset moves every growth tick 300 seconds earlier
		PatchState state = PatchDecoder.predict(PatchType.HERB, "32:" + SEEN_AT, SEEN_AT, 20, 5);
		assertEquals(new PatchState(PatchStatus.GROWING, SEEN_TICK - 300 + 4 * 20 * MINUTE), state);
	}

	@Test
	public void tickOffsetTooImpreciseForTheCropIsIgnored()
	{
		PatchState state = PatchDecoder.predict(PatchType.HERB, "32:" + SEEN_AT, SEEN_AT, 5, 3);
		assertEquals(new PatchState(PatchStatus.GROWING, SEEN_TICK + 4 * 20 * MINUTE), state);
	}

	@Test
	public void missingOrMalformedDataIsUnknown()
	{
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, null, SEEN_AT));
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, "", SEEN_AT));
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, "32", SEEN_AT));
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, "x:y", SEEN_AT));
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, "32:0", SEEN_AT));
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, "256:" + SEEN_AT, SEEN_AT));
		assertEquals(PatchState.UNKNOWN, predict(PatchType.HERB, "-1:" + SEEN_AT, SEEN_AT));
	}

	private static PatchState predict(PatchType type, String stored, long now)
	{
		return PatchDecoder.predict(type, stored, now, null, null);
	}

	@Test
	public void treeGrowsToItsHealthCheckThenStandsUntilRemoved()
	{
		// 1,000,000 is 1,600 seconds into a 40 minute growth tick that started at 998,400; 8 is a freshly planted oak
		long treeTick = 998_400;
		assertEquals(new PatchState(PatchStatus.GROWING, treeTick + 4 * 40 * MINUTE, Sapling.OAK),
			predict(PatchType.TREE, "8:" + SEEN_AT, SEEN_AT));
		assertEquals(new PatchState(PatchStatus.CHECK_HEALTH, 0, Sapling.OAK),
			predict(PatchType.TREE, "8:" + SEEN_AT, treeTick + 4 * 40 * MINUTE));
		assertEquals(new PatchState(PatchStatus.CHECK_HEALTH, 0, Sapling.OAK), predict(PatchType.TREE, "12:" + SEEN_AT, SEEN_AT));
		assertEquals(new PatchState(PatchStatus.GROWN, 0, Sapling.OAK), predict(PatchType.TREE, "13:" + SEEN_AT, SEEN_AT));
		assertEquals(new PatchState(PatchStatus.STUMP, 0, Sapling.OAK), predict(PatchType.TREE, "14:" + SEEN_AT, SEEN_AT));
		assertEquals(new PatchState(PatchStatus.CHECK_HEALTH, 0, Sapling.MAGIC), predict(PatchType.TREE, "60:" + SEEN_AT, SEEN_AT));
		assertEquals(PatchStatus.DISEASED, predict(PatchType.TREE, "113:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(PatchStatus.DEAD, predict(PatchType.TREE, "177:" + SEEN_AT, SEEN_AT).getStatus());
		assertEquals(new PatchState(PatchStatus.WEEDS, 0), predict(PatchType.TREE, "0:" + SEEN_AT, SEEN_AT));
	}

	@Test
	public void fruitTreeWithFruitCountsAsGrown()
	{
		// 34 is an apple tree waiting for its health check; 14 to 20 are apple trees with 0 to 6 apples
		assertEquals(new PatchState(PatchStatus.CHECK_HEALTH, 0, Sapling.APPLE), predict(PatchType.FRUIT_TREE, "34:" + SEEN_AT, SEEN_AT));
		for (int value = 14; value <= 20; value++)
		{
			assertEquals(new PatchState(PatchStatus.GROWN, 0, Sapling.APPLE), predict(PatchType.FRUIT_TREE, value + ":" + SEEN_AT, SEEN_AT));
		}
		assertEquals(new PatchState(PatchStatus.STUMP, 0, Sapling.APPLE), predict(PatchType.FRUIT_TREE, "33:" + SEEN_AT, SEEN_AT));
		assertEquals(new PatchState(PatchStatus.CHECK_HEALTH, 0, Sapling.DRAGONFRUIT), predict(PatchType.FRUIT_TREE, "253:" + SEEN_AT, SEEN_AT));
		// A fruit tree takes six 160 minute ticks
		assertEquals(PatchStatus.GROWING, predict(PatchType.FRUIT_TREE, "8:" + SEEN_AT, SEEN_AT).getStatus());
	}
}

